xhtml:iframe.style:
position:absolute;
inset:0;
width:100%;
height:100%;
border:0;
margin:0;
padding:0;
display:block;
overflow:auto;

svg.script:
(function () {

    const encoded = "";

    /*
     * Decode the original HTML without changing it.
     */
    const binary = atob(encoded);

    const bytes = new Uint8Array(binary.length);

    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }

    const html = new TextDecoder("utf-8").decode(bytes);

    const frame = document.getElementById("html-frame");

    if (!frame) {
        return;
    }

    /*
     * The original HTML goes into the iframe unchanged.
     */
    frame.srcdoc = html;

})();
